package com.dy.artisan3d.data.modelimport kotlinx.serialization.SerialNameimport kotlinx.serialization.Serializable@Serializabledata class ProductResponse(    @SerialName("data")    val data: ProductDetailsDto)@Serializabledata class ProductDetailsDto(    @SerialName("id")    val id: Int,    @SerialName("slug")    val slug: String,    @SerialName("product_status")    val productStatus: Int,    @SerialName("translations")    val translations: Map<String, ProductTranslation>,    @SerialName("category")    val category: CategoryDetailsDto,    @SerialName("brand")    val brand: BrandDetailsDto,    @SerialName("status")    val status: StatusDto,    @SerialName("details")    val details: List<ProductInfoDto>,    @SerialName("images")    val images: ProductImages,    @SerialName("created_at")    val createdAt: String,    @SerialName("updated_at")    val updatedAt: String)@Serializabledata class ProductTranslation(    @SerialName("name")    val name: String,    @SerialName("description")    val description: String)@Serializabledata class CategoryDetailsDto(    @SerialName("id")    val id: Int,    @SerialName("slug")    val slug: String,    @SerialName("translations")    val translations: Map<String, CategoryTranslation>)@Serializabledata class CategoryTranslation(    @SerialName("name")    val name: String)@Serializabledata class BrandDetailsDto(    @SerialName("id")    val id: Int,    @SerialName("image")    val image: String? = null,    @SerialName("brand_status")    val brandStatus: Int,    @SerialName("translations")    val translations: Map<String, BrandTranslation>)@Serializabledata class BrandTranslation(    @SerialName("name")    val name: String,    @SerialName("address")    val address: String)@Serializabledata class StatusDto(    @SerialName("id")    val id: Int,    @SerialName("slug")    val slug: String? = null,    @SerialName("translations")    val translations: Map<String, StatusTranslation>)@Serializabledata class StatusTranslation(    @SerialName("name")    val name: String)@Serializabledata class ProductInfoDto(    @SerialName("id")    val id: Int,    @SerialName("colors")    val colors: List<ColorDto>,    @SerialName("materials")    val materials: List<MaterialDto>,    @SerialName("tags")    val tags: List<TagDto>,    @SerialName("made_date")    val madeDate: String,    @SerialName("size")    val size: String? = null)@Serializabledata class ColorDto(    @SerialName("id")    val id: Int,    @SerialName("code")    val code: String,    @SerialName("translations")    val translations: Map<String, ColorTranslation>)@Serializabledata class ColorTranslation(    @SerialName("name")    val name: String)@Serializabledata class MaterialDto(    @SerialName("id")    val id: Int,    @SerialName("slug")    val slug: String,    @SerialName("translations")    val translations: Map<String, MaterialTranslation>)@Serializabledata class MaterialTranslation(    @SerialName("name")    val name: String)@Serializabledata class TagDto(    @SerialName("id")    val id: Int,    @SerialName("slug")    val slug: String,    @SerialName("translations")    val translations: Map<String, TagTranslation>)@Serializabledata class TagTranslation(    @SerialName("name")    val name: String)@Serializabledata class ProductImages(    @SerialName("main")    val main: String,    @SerialName("glb")    val glb: String,    @SerialName("extra")    val extra: List<String>)